local Modules = {}

Modules.CoreGui = game:GetService("CoreGui")
Modules.Players = game:GetService("Players")
Modules.TweenService = game:GetService("TweenService")
Modules.UserInputService = game:GetService("UserInputService")
Modules.TextService = game:GetService("TextService")

Modules.LocalPlayer = Modules.Players.LocalPlayer

Modules.setClipboardUrl = function(url)
    if setclipboard then
        setclipboard(url)
    elseif syn and syn.write_clipboard then
        syn.write_clipboard(url)
    end
end

Modules.getOption = function(cfg, keys, default)
    if type(cfg) ~= "table" then
        return default
    end
    for _, k in ipairs(keys) do
        if cfg[k] ~= nil then
            return cfg[k]
        end
    end
    for k, v in pairs(cfg) do
        if type(k) == "string" then
            local lk = string.lower(k)
            for _, targetKey in ipairs(keys) do
                if lk == string.lower(targetKey) then
                    return v
                end
            end
        end
    end
    return default
end

