local Library = {}
Library.__index = Library

function Library:CreateWindow(options)
    options = options or {}
    local windowTitle = Modules.getOption(options, {"Title", "Name"}, "LonelyLib Window")
    local windowDesc = Modules.getOption(options, {"Description", "Content"}, "Universal Roblox Interface")
    local windowThumb = Modules.getOption(options, {"Thumbnail"}, "rbxassetid://112485471724320")
    local windowLogo = Modules.getOption(options, {"Logo"}, "rbxassetid://112485471724320")
    local windowToggleIcon = Modules.getOption(options, {"ToogleIcon", "ToggleIcon"}, "rbxassetid://112485471724320")
    local youtubeUrl = Modules.getOption(options, {"Youtube"}, "https://youtube.com")
    local discordUrl = Modules.getOption(options, {"Discord"}, "https://discord.gg")
    local tiktokUrl = Modules.getOption(options, {"Tiktok"}, "https://tiktok.com")

    local selfObj = setmetatable({}, Library)
    selfObj.Tabs = {}
    selfObj.Shortcuts = nil
    selfObj.CurrentLevel = 1
    selfObj.ActiveTab = nil
    selfObj.ActiveSection = nil
    selfObj.Youtube = youtubeUrl
    selfObj.Discord = discordUrl
    selfObj.Tiktok = tiktokUrl

    local screenGui = Modules.buildMainGuiRaw()
    screenGui.Name = "LonelyLib_GUI"
    screenGui.ResetOnSpawn = false

    if gethui then
        screenGui.Parent = gethui()
    elseif syn and syn.protect_gui then
        syn.protect_gui(screenGui)
        screenGui.Parent = Modules.CoreGui
    elseif Modules.CoreGui:FindFirstChild("RobloxGui") then
        screenGui.Parent = Modules.CoreGui
    else
        screenGui.Parent = Modules.LocalPlayer:WaitForChild("PlayerGui")
    end
    selfObj.ScreenGui = screenGui

    local templatesGui = Modules.buildTemplatesRaw()
    selfObj.TemplatesGui = templatesGui

    local templatesMap = {}
    for _, child in ipairs(templatesGui:GetChildren()) do
        if child:IsA("GuiObject") then
            templatesMap[child.Name] = child
        end
    end
    selfObj.TemplatesMap = templatesMap

    local mainUI = screenGui:FindFirstChild("MAIN_UI", true)
    selfObj.MainUI = mainUI
    if mainUI then
        for _, scrollFrame in ipairs(mainUI:GetDescendants()) do
            if scrollFrame:IsA("ScrollingFrame") then
                selfObj:NormalizeScrollingFrame(scrollFrame)
            end
        end
    end

    local topBar = mainUI and mainUI:FindFirstChild("TOP_BAR", true)
    selfObj.TopBar = topBar
    if topBar and mainUI then
        local isDraggingMain = false
        local dragStartMain, startPosMain
        topBar.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDraggingMain = true
                dragStartMain = input.Position
                startPosMain = mainUI.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        isDraggingMain = false
                    end
                end)
            end
        end)
        Modules.UserInputService.InputChanged:Connect(function(input)
            if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and isDraggingMain then
                local delta = input.Position - dragStartMain
                mainUI.Position = UDim2.new(startPosMain.X.Scale, startPosMain.X.Offset + delta.X, startPosMain.Y.Scale, startPosMain.Y.Offset + delta.Y)
            end
        end)
    end

    local toggleBtn = screenGui:FindFirstChild("TOGGLE_APPEARANCE", true)
    if toggleBtn then
        local toggleLogo = toggleBtn:FindFirstChild("Logo", true)
        if toggleLogo and toggleLogo:IsA("ImageLabel") then
            toggleLogo.Image = windowToggleIcon
        end
        local trigger = toggleBtn:IsA("TextButton") and toggleBtn or toggleBtn:FindFirstChildOfClass("TextButton")
        if not trigger then
            trigger = Instance.new("TextButton")
            trigger.Size = UDim2.new(1, 0, 1, 0)
            trigger.BackgroundTransparency = 1
            trigger.Text = ""
            trigger.Parent = toggleBtn
        end
        trigger.MouseButton1Click:Connect(function()
            if mainUI then
                mainUI.Visible = not mainUI.Visible
            end
        end)

        local isDragging = false
        local dragInput, dragStart, startPos
        toggleBtn.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = true
                dragStart = input.Position
                startPos = toggleBtn.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        isDragging = false
                    end
                end)
            end
        end)
        toggleBtn.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                dragInput = input
            end
        end)
        Modules.UserInputService.InputChanged:Connect(function(input)
            if input == dragInput and isDragging then
                local delta = input.Position - dragStart
                toggleBtn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end)
    end

    if topBar then
        local logo = topBar:FindFirstChild("HUB_LOGO", true)
        if logo and logo:IsA("ImageLabel") then
            logo.Image = windowLogo
        end
        local topHome = topBar:FindFirstChild("TOP_HOME", true)
        local topPages = topBar:FindFirstChild("TOP_PAGES", true)
        local topCredits = topBar:FindFirstChild("TOP_CREDITS", true)

        selfObj.TopHome = topHome
        selfObj.TopPages = topPages
        selfObj.TopCredits = topCredits

        local function hookNavBtn(btnObj, targetTab)
            if btnObj then
                local triggerBtn = btnObj:IsA("TextButton") and btnObj or btnObj:FindFirstChildOfClass("TextButton")
                if not triggerBtn then
                    triggerBtn = Instance.new("TextButton")
                    triggerBtn.Size = UDim2.new(1, 0, 1, 0)
                    triggerBtn.BackgroundTransparency = 1
                    triggerBtn.Text = ""
                    triggerBtn.Parent = btnObj
                end
                triggerBtn.MouseButton1Click:Connect(function()
                    selfObj:SwitchTab(targetTab)
                end)
            end
        end

        hookNavBtn(topHome, "Home")
        hookNavBtn(topPages, "Pages")
        hookNavBtn(topCredits, "Credits")
    end

    local mainZones = mainUI and mainUI:FindFirstChild("MAIN_ZONES", true)
    selfObj.MainZones = mainZones

    local homeTab = mainZones and mainZones:FindFirstChild("HOME_TAB", true)
    selfObj.HomeTab = homeTab
    if homeTab then
        homeTab.AnchorPoint = Vector2.new(0.5, 0.5)
        homeTab.Position = UDim2.new(0.5, 0, 0.5, 0)
    end

    local pagesTab = mainZones and mainZones:FindFirstChild("PAGES_TAB", true)
    selfObj.PagesTab = pagesTab
    if pagesTab then
        pagesTab.AnchorPoint = Vector2.new(0.5, 0.5)
        pagesTab.Position = UDim2.new(0.5, 0, 0.5, 0)
    end

    local creditsTab = mainZones and mainZones:FindFirstChild("CREDITS_TAB", true)
    selfObj.CreditsTab = creditsTab
    if creditsTab then
        creditsTab.AnchorPoint = Vector2.new(0.5, 0.5)
        creditsTab.Position = UDim2.new(0.5, 0, 0.5, 0)
    end

    if homeTab then
        local upper = homeTab:FindFirstChild("Upper", true)
        if upper then
            local banner = upper:FindFirstChild("UPDATE_BANNER1", true)
            if banner and banner:IsA("ImageLabel") then
                banner.Image = windowThumb
            end

            local socials = upper:FindFirstChild("SOCIALS_BUTTONS", true)
            if socials then
                local b1 = socials:FindFirstChild("1", true)
                local b2 = socials:FindFirstChild("2", true)
                local b3 = socials:FindFirstChild("3", true)

                local function hookSocial(btn, urlKey)
                    if btn then
                        local trigger = btn:IsA("ImageButton") and btn or btn:FindFirstChildOfClass("ImageButton")
                        if not trigger then
                            trigger = Instance.new("ImageButton")
                            trigger.Size = UDim2.new(1, 0, 1, 0)
                            trigger.BackgroundTransparency = 1
                            trigger.Parent = btn
                        end
                        trigger.MouseButton1Click:Connect(function()
                            Modules.setClipboardUrl(selfObj[urlKey])
                        end)
                    end
                end

                hookSocial(b1, "Discord")
                hookSocial(b2, "Youtube")
                hookSocial(b3, "Tiktok")
            end
        end

        local shortcutsFrame = homeTab:FindFirstChild("PAGE_SHORTCUTS", true)
        selfObj.ShortcutsFrame = shortcutsFrame
    end

    if creditsTab then
        local upper = creditsTab:FindFirstChild("Upper", true)
        if upper then
            local copyInv = upper:FindFirstChild("Copy Invite", true)
            if copyInv then
                local trigger = copyInv:IsA("TextButton") and copyInv or copyInv:FindFirstChildOfClass("TextButton")
                if not trigger then
                    trigger = Instance.new("TextButton")
                    trigger.Size = UDim2.new(1, 0, 1, 0)
                    trigger.BackgroundTransparency = 1
                    trigger.Text = ""
                    trigger.Parent = copyInv
                end
                trigger.MouseButton1Click:Connect(function()
                    Modules.setClipboardUrl(selfObj.Discord)
                end)
            end
        end

        local contribSf = creditsTab:FindFirstChild("ScrollingFrame", true)
        if contribSf then
            for _, child in ipairs(contribSf:GetChildren()) do
                if child:IsA("TextLabel") then
                    if string.find(child.Text, "LongHip12") then
                        child.Name = "Contributor1"
                        child.RichText = true
                    elseif string.find(child.Text, "Lonely Hub") then
                        child.Name = "Contributor2"
                        child.RichText = true
                    end
                end
            end
        end
    end

    if pagesTab then
        local deepSearchModal = pagesTab:FindFirstChild("DEEP_SEARCH", true)
        selfObj.DeepSearchModal = deepSearchModal
        if deepSearchModal then
            deepSearchModal.AnchorPoint = Vector2.new(0.5, 0.5)
            deepSearchModal.Position = UDim2.new(0.5, 0, 0.5, 0)
            deepSearchModal.Visible = false

            local closeBtn = deepSearchModal:FindFirstChild("CloseBtn", true)
            if closeBtn then
                local trigger = closeBtn:IsA("TextButton") and closeBtn or closeBtn:FindFirstChildOfClass("TextButton")
                if not trigger then trigger = closeBtn end
                trigger.MouseButton1Click:Connect(function()
                    deepSearchModal.Visible = false
                end)
            end

            local filterBox = deepSearchModal:FindFirstChild("FilterBox", true)
            selfObj.DeepFilterBox = filterBox and filterBox:FindFirstChildOfClass("TextBox") or filterBox
            if selfObj.DeepFilterBox then
                selfObj.DeepFilterBox:GetPropertyChangedSignal("Text"):Connect(function()
                    selfObj:UpdateDeepSearch(selfObj.DeepFilterBox.Text)
                end)
            end
        end

        local anchor = pagesTab:FindFirstChild("ANCHOR", true)
        if anchor then
            anchor.AnchorPoint = Vector2.new(0.5, 0.5)
            anchor.Position = UDim2.new(0.5, 0, 0.5, 0)
            selfObj.Anchor = anchor

            selfObj.MainPages = anchor:FindFirstChild("MAIN_PAGES", true)
            selfObj.MiniPages = anchor:FindFirstChild("MINI_PAGES", true)
            selfObj.ConfigPages = anchor:FindFirstChild("CONFIG_PAGES", true)

            if selfObj.MainPages then
                selfObj.MainPages.AnchorPoint = Vector2.new(0.5, 0.5)
                selfObj.MainPages.Position = UDim2.new(0.5, 0, 0.5, 0)

                local sb = selfObj.MainPages:FindFirstChild("SearchBox", true)
                if sb then selfObj:SetupSearchBox(sb, 1) end

                local secSf = selfObj.MainPages:FindFirstChild("ScrollingFrame", true)
                if secSf then
                    local grid = secSf:FindFirstChildOfClass("UIGridLayout") or secSf:FindFirstChildOfClass("UIListLayout")
                    if grid and grid:IsA("UIGridLayout") then
                        grid.CellPadding = UDim2.new(0, 5, 0, 5)
                    end
                    local t1 = secSf:FindFirstChild("MAIN_1")
                    if t1 then
                        selfObj.TabTemplate = t1:Clone()
                        t1.Visible = false
                    end
                end
            end

            if selfObj.MiniPages then
                selfObj.MiniPages.AnchorPoint = Vector2.new(0.5, 0.5)
                selfObj.MiniPages.Position = UDim2.new(0.5, 0, 0.5, 0)

                local sb = selfObj.MiniPages:FindFirstChild("SearchBox", true)
                if sb then selfObj:SetupSearchBox(sb, 2) end

                local retBtn = selfObj.MiniPages:FindFirstChild("RETURN_BUTTON", true)
                if retBtn then
                    local trigger = retBtn:IsA("TextButton") and retBtn or retBtn:FindFirstChildOfClass("TextButton")
                    if not trigger then
                        trigger = Instance.new("TextButton")
                        trigger.Size = UDim2.new(1, 0, 1, 0)
                        trigger.BackgroundTransparency = 1
                        trigger.Text = ""
                        trigger.Parent = retBtn
                    end
                    trigger.MouseButton1Click:Connect(function()
                        selfObj:ShowLevel(1)
                    end)
                end

                local mini1 = selfObj.MiniPages:FindFirstChild("MINI_1", true)
                if mini1 then
                    mini1.Visible = true
                    local sf = mini1:FindFirstChild("ScrollingFrame", true)
                    if sf then
                        local grid = sf:FindFirstChildOfClass("UIGridLayout") or sf:FindFirstChildOfClass("UIListLayout")
                        if grid and grid:IsA("UIGridLayout") then
                            grid.CellPadding = UDim2.new(0, 5, 0, 5)
                        end
                        local btnTmpl = sf:FindFirstChild("Button")
                        if btnTmpl then
                            selfObj.SecTemplate = btnTmpl:Clone()
                            btnTmpl.Visible = false
                        end
                    end
                end
            end

            if selfObj.ConfigPages then
                selfObj.ConfigPages.AnchorPoint = Vector2.new(0.5, 0.5)
                selfObj.ConfigPages.Position = UDim2.new(0.5, 0, 0.5, 0)

                local sb = selfObj.ConfigPages:FindFirstChild("SearchBox", true)
                if sb then selfObj:SetupSearchBox(sb, 3) end

                local miniConfig = selfObj.ConfigPages:FindFirstChild("MINI_9_CONFIG_3", true)
                if miniConfig then
                    miniConfig.Visible = true
                end

                local retBtn = selfObj.ConfigPages:FindFirstChild("RETURN_BUTTON", true)
                if retBtn then
                    local trigger = retBtn:IsA("TextButton") and retBtn or retBtn:FindFirstChildOfClass("TextButton")
                    if not trigger then
                        trigger = Instance.new("TextButton")
                        trigger.Size = UDim2.new(1, 0, 1, 0)
                        trigger.BackgroundTransparency = 1
                        trigger.Text = ""
                        trigger.Parent = retBtn
                    end
                    trigger.MouseButton1Click:Connect(function()
                        selfObj:ShowLevel(2, selfObj.ActiveTab)
                    end)
                end
            end
        end
    end

    local notiZone = screenGui:FindFirstChild("NOTIFICATION_ZONE", true)
    selfObj.NotiZone = notiZone
    if notiZone then
        local n1 = notiZone:FindFirstChild("Noti1", true)
        local n2 = notiZone:FindFirstChild("Noti2", true)
        if n1 then
            n1.Visible = false
            selfObj.Noti1Template = n1:Clone()
        end
        if n2 then
            n2.Visible = false
            selfObj.Noti2Template = n2:Clone()
        end
    end

    selfObj:SwitchTab("Home")
    return selfObj
end

function Library:SetupSearchBox(searchBox, level)
    if not searchBox then return end
    local tb = searchBox:FindFirstChildOfClass("TextBox") or searchBox:FindFirstChild("Textbox", true)
    if tb and tb:IsA("TextBox") then
        tb:GetPropertyChangedSignal("Text"):Connect(function()
            self:FilterCurrentLevel(tb.Text, level)
        end)
    end

    local deepBtn = searchBox:FindFirstChild("DeepSearchBtn", true)
    if deepBtn then
        local trigger = deepBtn:IsA("TextButton") and deepBtn or deepBtn:FindFirstChildOfClass("TextButton")
        if not trigger then trigger = deepBtn end
        trigger.MouseButton1Click:Connect(function()
            if self.DeepSearchModal then
                self.DeepSearchModal.Visible = true
                if self.DeepFilterBox then
                    self.DeepFilterBox.Text = tb and tb.Text or ""
                    self.DeepFilterBox:CaptureFocus()
                end
                self:UpdateDeepSearch(self.DeepFilterBox and self.DeepFilterBox.Text or "")
            end
        end)
    end
end

function Library:FilterCurrentLevel(query, level)
    query = string.lower(query or "")
    if level == 1 and self.MainPages then
        local secSf = self.MainPages:FindFirstChild("ScrollingFrame", true)
        if secSf then
            for _, child in ipairs(secSf:GetChildren()) do
                if child:IsA("GuiObject") and child.Name ~= "MAIN_1" then
                    if query == "" then
                        child.Visible = true
                    else
                        local tLbl = child:FindFirstChild("Title", true)
                        local dLbl = child:FindFirstChild("Desc", true)
                        local tText = string.lower(tLbl and tLbl.Text or "")
                        local dText = string.lower(dLbl and dLbl.Text or "")
                        child.Visible = (string.find(tText, query) ~= nil or string.find(dText, query) ~= nil)
                    end
                end
            end
        end
    elseif level == 2 and self.MiniPages then
        local mini1 = self.MiniPages:FindFirstChild("MINI_1", true)
        local secSf = mini1 and mini1:FindFirstChild("ScrollingFrame", true)
        if secSf then
            for _, child in ipairs(secSf:GetChildren()) do
                if child:IsA("GuiObject") and child ~= self.SecTemplate then
                    if query == "" then
                        child.Visible = true
                    else
                        local tLbl = child:FindFirstChild("Title", true)
                        local dLbl = child:FindFirstChild("Desc", true)
                        local tText = string.lower(tLbl and tLbl.Text or "")
                        local dText = string.lower(dLbl and dLbl.Text or "")
                        child.Visible = (string.find(tText, query) ~= nil or string.find(dText, query) ~= nil)
                    end
                end
            end
        end
    elseif level == 3 and self.ConfigPages then
        local miniConfig = self.ConfigPages:FindFirstChild("MINI_9_CONFIG_3", true)
        local mainSf = miniConfig and miniConfig:FindFirstChild("ScrollingFrame", true)
        if mainSf then
            local t1 = mainSf:FindFirstChild("Tab1", true)
            local t2 = mainSf:FindFirstChild("Tab2", true)
            local function filterCol(col)
                if not col then return end
                for _, child in ipairs(col:GetChildren()) do
                    if child:IsA("GuiObject") then
                        if query == "" then
                            child.Visible = true
                        else
                            local tLbl = child:FindFirstChild("Title", true)
                            local tText = string.lower(tLbl and tLbl.Text or "")
                            child.Visible = (string.find(tText, query) ~= nil)
                        end
                    end
                end
            end
            filterCol(t1)
            filterCol(t2)
        end
    end
end

function Library:UpdateDeepSearch(query)
    if not self.DeepSearchModal then return end
    local scrollFrame = self.DeepSearchModal:FindFirstChild("ScrollFrame", true) or self.DeepSearchModal:FindFirstChildOfClass("ScrollingFrame")
    local holder = scrollFrame and (scrollFrame:FindFirstChild("SearchHolder", true) or scrollFrame)
    if not holder then return end

    for _, child in ipairs(holder:GetChildren()) do
        if child:IsA("GuiObject") then
            child:Destroy()
        end
    end

    query = string.lower(query or "")
    if query == "" then return end

    for _, tabObj in ipairs(self.Tabs) do
        if string.find(string.lower(tabObj.Title), query) or string.find(string.lower(tabObj.Description), query) then
            self:CreateSearchResult(holder, "[Section] " .. tabObj.Title, function()
                self.DeepSearchModal.Visible = false
                self:SwitchTab("Pages")
                self:ShowLevel(2, tabObj)
            end)
        end

        for _, secObj in ipairs(tabObj.Sections) do
            if string.find(string.lower(secObj.Title), query) or string.find(string.lower(secObj.Description), query) then
                self:CreateSearchResult(holder, "[Section] " .. tabObj.Title .. " > " .. secObj.Title, function()
                    self.DeepSearchModal.Visible = false
                    self:SwitchTab("Pages")
                    self:ShowLevel(3, secObj)
                end)
            end

            for _, elem in ipairs(secObj.Elements) do
                if string.find(string.lower(elem.Title), query) then
                    self:CreateSearchResult(holder, "[Element] " .. tabObj.Title .. " > " .. secObj.Title .. " > " .. elem.Title, function()
                        self.DeepSearchModal.Visible = false
                        self:SwitchTab("Pages")
                        self:ShowLevel(3, secObj)
                    end)
                end
            end
        end
    end
end

function Library:CreateSearchResult(parent, textContent, onClick)
    local TextLabel = Instance.new("TextLabel")
    TextLabel.Parent = parent
    TextLabel.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    TextLabel.BackgroundTransparency = 1.000
    TextLabel.BorderColor3 = Color3.fromRGB(0, 0, 0)
    TextLabel.BorderSizePixel = 0
    TextLabel.Position = UDim2.new(0.0202479828, 0, 0, 0)
    TextLabel.Size = UDim2.new(0, 918, 0, 50)
    TextLabel.Font = Enum.Font.SourceSansBold
    TextLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    TextLabel.TextSize = 14.000
    TextLabel.TextXAlignment = Enum.TextXAlignment.Left
    TextLabel.RichText = true
    TextLabel.Text = textContent

    local trigger = Instance.new("TextButton")
    trigger.Size = UDim2.new(1, 0, 1, 0)
    trigger.BackgroundTransparency = 1
    trigger.Text = ""
    trigger.Parent = TextLabel
    trigger.MouseButton1Click:Connect(onClick)
end

function Library:NormalizeScrollingFrame(scrollFrame)
    if not scrollFrame or not scrollFrame:IsA("ScrollingFrame") then return end

    scrollFrame.ClipsDescendants = true
    scrollFrame.AutomaticCanvasSize = Enum.AutomaticSize.None
    scrollFrame.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable

    local layout = scrollFrame:FindFirstChildOfClass("UIListLayout") or scrollFrame:FindFirstChildOfClass("UIGridLayout")
    if not layout then
        local searchHolder = scrollFrame:FindFirstChild("SearchHolder")
        if searchHolder then
            layout = searchHolder:FindFirstChildOfClass("UIListLayout") or searchHolder:FindFirstChildOfClass("UIGridLayout")
        end
    end
    if not layout then return end

    if scrollFrame:GetAttribute("LonelyLibScrollBound") then return end
    scrollFrame:SetAttribute("LonelyLibScrollBound", true)

    local function syncCanvas()
        local contentY = layout.AbsoluteContentSize.Y
        local frameY = scrollFrame.AbsoluteSize.Y
        if contentY > frameY and frameY > 0 then
            scrollFrame.CanvasSize = UDim2.new(0, 0, 0, contentY + 10)
        else
            scrollFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
        end
    end

    layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncCanvas)
    scrollFrame:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncCanvas)
    task.defer(syncCanvas)
end

function Library:SwitchTab(tabName)
    if self.HomeTab then self.HomeTab.Visible = (tabName == "Home") end
    if self.PagesTab then self.PagesTab.Visible = (tabName == "Pages") end
    if self.CreditsTab then self.CreditsTab.Visible = (tabName == "Credits") end

    local function updateTopTitle(topFrame, isSelected)
        if topFrame then
            local titleLbl = topFrame:FindFirstChild("Title", true)
            if titleLbl and titleLbl:IsA("TextLabel") then
                if isSelected then
                    titleLbl.TextColor3 = Color3.fromRGB(255, 50, 50)
                    titleLbl.TextTransparency = 0
                else
                    titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
                    titleLbl.TextTransparency = 0.5
                end
            end
        end
    end

    updateTopTitle(self.TopHome, tabName == "Home")
    updateTopTitle(self.TopPages, tabName == "Pages")
    updateTopTitle(self.TopCredits, tabName == "Credits")

    if tabName == "Pages" then
        self:ShowLevel(1)
    end
end

function Library:SetCreditsInfo(info)
    info = info or {}
    local titleText = Modules.getOption(info, {"Title"}, nil)
    local memText = Modules.getOption(info, {"MemberText", "Mems"}, nil)
    local credText = Modules.getOption(info, {"CreditText", "Credits"}, nil)
    local contrib1 = Modules.getOption(info, {"Contributor1"}, nil)
    local contrib2 = Modules.getOption(info, {"Contributor2"}, nil)
    local inviteLink = Modules.getOption(info, {"InviteLink"}, nil)
    local pfpImage = Modules.getOption(info, {"Image"}, nil)

    if inviteLink then self.Discord = inviteLink end

    if self.CreditsTab then
        local upper = self.CreditsTab:FindFirstChild("Upper", true)
        if upper then
            if titleText then
                local invLbl = upper:FindFirstChild("Invitation", true)
                if invLbl and invLbl:IsA("TextLabel") then
                    invLbl.RichText = true
                    invLbl.Text = titleText
                end
            end
            if memText then
                local memsLbl = upper:FindFirstChild("Mems", true)
                if memsLbl and memsLbl:IsA("TextLabel") then
                    memsLbl.RichText = true
                    memsLbl.Text = memText
                end
            end
            if credText then
                local credsLbl = upper:FindFirstChild("Credits", true)
                if credsLbl and credsLbl:IsA("TextLabel") then
                    credsLbl.RichText = true
                    credsLbl.Text = credText
                end
            end
            if pfpImage then
                local pfpImg = upper:FindFirstChild("Pfp", true)
                if pfpImg and pfpImg:IsA("ImageLabel") then
                    pfpImg.Image = pfpImage
                end
            end
        end

        local contribSf = self.CreditsTab:FindFirstChild("ScrollingFrame", true)
        if contribSf then
            if contrib1 then
                local c1 = contribSf:FindFirstChild("Contributor1", true)
                if c1 and c1:IsA("TextLabel") then
                    c1.RichText = true
                    c1.Text = contrib1
                end
            end
            if contrib2 then
                local c2 = contribSf:FindFirstChild("Contributor2", true)
                if c2 and c2:IsA("TextLabel") then
                    c2.RichText = true
                    c2.Text = contrib2
                end
            end
        end
    end
end

function Library:Notify(options)
    options = options or {}
    local titleText = Modules.getOption(options, {"Title", "Name"}, "Notification")
    local descText = Modules.getOption(options, {"Description", "Content"}, "Notification content message")
    local duration = Modules.getOption(options, {"Duration", "Time"}, 4)
    local callback = Modules.getOption(options, {"Callback", "callback"}, nil)
    local iconImage = Modules.getOption(options, {"Image", "Icon"}, nil)

    if not self.NotiZone then return end

    local notiCard = nil
    if type(callback) == "function" and self.Noti2Template then
        notiCard = self.Noti2Template:Clone()
    elseif self.Noti1Template then
        notiCard = self.Noti1Template:Clone()
    end

    if not notiCard then return end

    notiCard.Visible = true
    notiCard.Parent = self.NotiZone

    local mainFrame = notiCard:FindFirstChild("Main", true) or notiCard
    local titleLbl = mainFrame:FindFirstChild("Title", true)
    if titleLbl and titleLbl:IsA("TextLabel") then
        titleLbl.RichText = true
        titleLbl.Text = titleText
    end

    for _, child in ipairs(mainFrame:GetChildren()) do
        if child:IsA("TextLabel") and child.Name ~= "Title" then
            child.RichText = true
            child.Text = descText
            break
        end
    end

    if iconImage then
        local iconImg = mainFrame:FindFirstChild("Icon", true)
        if iconImg and iconImg:IsA("ImageLabel") then
            iconImg.Image = iconImage
        end
    end

    local cooldownMain = nil
    local cooldownFrame = mainFrame:FindFirstChild("Cooldown", true)
    if cooldownFrame then
        cooldownMain = cooldownFrame:FindFirstChild("Main", true)
    end

    local tween = nil
    if cooldownMain then
        cooldownMain.Size = UDim2.new(0.994, 0, 1, 0)
        local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)
        tween = Modules.TweenService:Create(cooldownMain, tweenInfo, { Size = UDim2.new(0, 0, 1, 0) })
        tween.Completed:Connect(function()
            if notiCard and notiCard.Parent then
                notiCard:Destroy()
            end
        end)
        tween:Play()
    else
        task.delay(duration, function()
            if notiCard and notiCard.Parent then
                notiCard:Destroy()
            end
        end)
    end

    local okBtn = mainFrame:FindFirstChild("OK", true)
    if okBtn then
        local trigger = okBtn:IsA("TextButton") and okBtn or okBtn:FindFirstChildOfClass("TextButton")
        if not trigger then trigger = okBtn end
        trigger.MouseButton1Click:Connect(function()
            if tween then tween:Cancel() end
            if type(callback) == "function" then
                callback(true)
            end
            if notiCard and notiCard.Parent then
                notiCard:Destroy()
            end
        end)
    end

    local nopeBtn = mainFrame:FindFirstChild("Nope", true)
    if nopeBtn then
        local trigger = nopeBtn:IsA("TextButton") and nopeBtn or nopeBtn:FindFirstChildOfClass("TextButton")
        if not trigger then trigger = nopeBtn end
        trigger.MouseButton1Click:Connect(function()
            if tween then tween:Cancel() end
            if notiCard and notiCard.Parent then
                notiCard:Destroy()
            end
        end)
    end
end

function Library:ShowLevel(level, data)
    self.CurrentLevel = level
    if self.MainPages then self.MainPages.Visible = (level == 1) end
    if self.MiniPages then self.MiniPages.Visible = (level == 2) end
    if self.ConfigPages then self.ConfigPages.Visible = (level == 3) end

    if level == 1 then
        self:RenderLevel1()
    elseif level == 2 then
        self.ActiveTab = data
        if self.MiniPages then
            local mini1 = self.MiniPages:FindFirstChild("MINI_1", true)
            if mini1 then mini1.Visible = true end
        end
        self:RenderLevel2()
    elseif level == 3 then
        self.ActiveSection = data
        if self.ConfigPages then
            local miniConfig = self.ConfigPages:FindFirstChild("MINI_9_CONFIG_3", true)
            if miniConfig then miniConfig.Visible = true end
        end
        self:RenderLevel3()
    end
end

function Library:RenderLevel1()
    if not self.MainPages then return end
    local secSf = self.MainPages:FindFirstChild("ScrollingFrame", true)
    if not secSf then return end

    for _, child in ipairs(secSf:GetChildren()) do
        if child:IsA("GuiObject") and child.Name ~= "MAIN_1" then
            child:Destroy()
        end
    end

    for _, tabObj in ipairs(self.Tabs) do
        local card = nil
        if self.TabTemplate then
            card = self.TabTemplate:Clone()
        else
            card = Instance.new("TextButton")
            card.Size = UDim2.new(0, 140, 0, 140)
        end

        card.Name = "TAB_CARD_" .. tabObj.Title
        card.Visible = true
        card.Parent = secSf

        local titleLbl = card:FindFirstChild("Title", true)
        if titleLbl and titleLbl:IsA("TextLabel") then
            titleLbl.RichText = true
            titleLbl.Text = tabObj.Title
        end

        local descLbl = card:FindFirstChild("Desc", true)
        if descLbl and descLbl:IsA("TextLabel") then
            descLbl.RichText = true
            descLbl.Text = tabObj.Description
        end

        local logoImg = card:FindFirstChild("Logo", true) or card:FindFirstChild("Icon", true)
        if logoImg and logoImg:IsA("ImageLabel") and tabObj.Image then
            logoImg.Image = tabObj.Image
        end

        local trigger = card:IsA("TextButton") and card or card:FindFirstChildOfClass("TextButton")
        if not trigger then
            trigger = Instance.new("TextButton")
            trigger.Size = UDim2.new(1, 0, 1, 0)
            trigger.BackgroundTransparency = 1
            trigger.Text = ""
            trigger.Parent = card
        end
        trigger.MouseButton1Click:Connect(function()
            self:ShowLevel(2, tabObj)
        end)
    end
    self:NormalizeScrollingFrame(secSf)
    secSf.CanvasPosition = Vector2.new(0, 0)
end

function Library:RenderLevel2()
    if not self.MiniPages or not self.ActiveTab then return end
    local mini1 = self.MiniPages:FindFirstChild("MINI_1", true)
    if mini1 then mini1.Visible = true end

    local secSf = mini1 and mini1:FindFirstChild("ScrollingFrame", true)
    if not secSf then return end

    for _, child in ipairs(secSf:GetChildren()) do
        if child:IsA("GuiObject") and child ~= self.SecTemplate then
            child:Destroy()
        end
    end

    for _, secObj in ipairs(self.ActiveTab.Sections) do
        local card = nil
        if self.SecTemplate then
            card = self.SecTemplate:Clone()
        else
            card = Instance.new("TextButton")
            card.Size = UDim2.new(0, 140, 0, 140)
        end

        card.Name = "SEC_CARD_" .. secObj.Title
        card.Visible = true
        card.Parent = secSf

        local titleLbl = card:FindFirstChild("Title", true)
        if titleLbl and titleLbl:IsA("TextLabel") then
            titleLbl.RichText = true
            titleLbl.Text = secObj.Title
        end

        local descLbl = card:FindFirstChild("Desc", true)
        if descLbl and descLbl:IsA("TextLabel") then
            descLbl.RichText = true
            descLbl.Text = secObj.Description
        end

        local displayImg = card:FindFirstChild("Display", true)
        if displayImg and displayImg:IsA("ImageLabel") and secObj.Image then
            displayImg.Image = secObj.Image
        end

        local trigger = card:IsA("TextButton") and card or card:FindFirstChildOfClass("TextButton")
        if not trigger then
            trigger = Instance.new("TextButton")
            trigger.Size = UDim2.new(1, 0, 1, 0)
            trigger.BackgroundTransparency = 1
            trigger.Text = ""
            trigger.Parent = card
        end
        trigger.MouseButton1Click:Connect(function()
            self:ShowLevel(3, secObj)
        end)
    end
    self:NormalizeScrollingFrame(secSf)
    secSf.CanvasPosition = Vector2.new(0, 0)
end

function Library:RenderLevel3()
    if not self.ConfigPages or not self.ActiveSection then return end
    local miniConfig = self.ConfigPages:FindFirstChild("MINI_9_CONFIG_3", true)
    if miniConfig then miniConfig.Visible = true end

    local mainSf = miniConfig and miniConfig:FindFirstChild("ScrollingFrame", true)
    if not mainSf then return end

    local tab1 = mainSf:FindFirstChild("Tab1", true)
    local tab2 = mainSf:FindFirstChild("Tab2", true)
    if not tab1 or not tab2 then return end

    for _, child in ipairs(tab1:GetChildren()) do
        if child:IsA("GuiObject") then
            child:Destroy()
        end
    end
    for _, child in ipairs(tab2:GetChildren()) do
        if child:IsA("GuiObject") then
            child:Destroy()
        end
    end

    mainSf.ClipsDescendants = true
    mainSf.AutomaticCanvasSize = Enum.AutomaticSize.None

    for _, elem in ipairs(self.ActiveSection.Elements) do
        local kind = elem.Kind
        local tmpl = nil
        if kind == "Toggle" then tmpl = self.TemplatesMap["Checkbox"]
        elseif kind == "Button" then tmpl = self.TemplatesMap["Button"]
        elseif kind == "ButtonGroup" then tmpl = self.TemplatesMap["Button_Group"]
        elseif kind == "Dropdown" then tmpl = elem.Multi and self.TemplatesMap["Selector_Multiple"] or self.TemplatesMap["Selector_Single"]
        elseif kind == "Slider" then tmpl = self.TemplatesMap["Slider"]
        elseif kind == "Colorpicker" then tmpl = self.TemplatesMap["ColorPicker"]
        elseif kind == "Label" then tmpl = self.TemplatesMap["Label"]
        elseif kind == "ImageLabel" then tmpl = self.TemplatesMap["Image"]
        elseif kind == "Paragraph" then tmpl = self.TemplatesMap["Paragraph"]
        elseif kind == "Input" then tmpl = self.TemplatesMap["Textbox2"]
        end

        local itemObj = nil
        if tmpl then
            itemObj = tmpl:Clone()
        elseif kind == "Slider" then
            itemObj = Instance.new("Frame")
            itemObj.Name = "Slider"
            itemObj.BackgroundTransparency = 1
            itemObj.BorderSizePixel = 0
            itemObj.Size = UDim2.new(1, 0, 0, 72)

            local sliderTitle = Instance.new("TextLabel")
            sliderTitle.Name = "Title"
            sliderTitle.Font = Enum.Font.SourceSansBold
            sliderTitle.TextColor3 = Color3.fromRGB(255, 255, 255)
            sliderTitle.TextScaled = true
            sliderTitle.TextWrapped = true
            sliderTitle.TextXAlignment = Enum.TextXAlignment.Left
            sliderTitle.BackgroundTransparency = 1
            sliderTitle.Position = UDim2.new(0.05, 0, 0, 5)
            sliderTitle.Size = UDim2.new(0.9, 0, 0, 28)
            sliderTitle.Parent = itemObj
        else
            itemObj = Instance.new("Frame")
        end

        itemObj.Visible = true
        if kind == "Label" then
            itemObj.Size = UDim2.new(1, 0, 0, 40)
        end
        if elem.Side == "Right" then
            itemObj.Parent = tab2
        else
            itemObj.Parent = tab1
        end

        local titleLbl = itemObj:FindFirstChild("Title", true)
        if titleLbl and titleLbl:IsA("TextLabel") then
            titleLbl.RichText = true
            titleLbl.Text = elem.Title
        end

        if kind == "Toggle" then
            local toggleBtn = itemObj:FindFirstChild("Toggle", true)
            local toggled = elem.Default or false

            local function updateToggleVisual()
                if toggleBtn then
                    local inner = toggleBtn:FindFirstChild("Inner", true)
                    local outer = toggleBtn:FindFirstChild("Outer", true)
                    if inner then
                        inner.Visible = toggled
                        inner.ImageColor3 = Color3.fromRGB(248, 4, 46)
                    end
                    if outer then
                        outer.ImageColor3 = toggled and Color3.fromRGB(248, 4, 46) or Color3.fromRGB(150, 150, 150)
                    end
                    local holder = toggleBtn:FindFirstChild("Holder", true)
                    if holder then
                        holder.BackgroundColor3 = toggled and Color3.fromRGB(248, 4, 46) or Color3.fromRGB(40, 40, 40)
                    end
                end
            end
            updateToggleVisual()

            local mainTrigger = itemObj:IsA("TextButton") and itemObj or itemObj:FindFirstChildOfClass("TextButton")
            local toggleTrigger = toggleBtn and (toggleBtn:IsA("TextButton") and toggleBtn or toggleBtn:FindFirstChildOfClass("TextButton"))

            local function onToggleClick()
                toggled = not toggled
                updateToggleVisual()
                if elem.Callback then elem.Callback(toggled) end
            end

            if mainTrigger then mainTrigger.MouseButton1Click:Connect(onToggleClick) end
            if toggleTrigger and toggleTrigger ~= mainTrigger then toggleTrigger.MouseButton1Click:Connect(onToggleClick) end

        elseif kind == "Button" then
            local trigger = itemObj:IsA("TextButton") and itemObj or itemObj:FindFirstChildOfClass("TextButton")
            if trigger then
                trigger.MouseButton1Click:Connect(function()
                    if elem.Callback then elem.Callback() end
                end)
            end

        elseif kind == "ButtonGroup" then
            local groupFrame = itemObj:FindFirstChild("Group", true)
            if groupFrame and elem.Buttons then
                local tmplBtn = groupFrame:FindFirstChild("Button")
                local buttonTemplate = tmplBtn and tmplBtn:Clone()
                for _, child in ipairs(groupFrame:GetChildren()) do
                    if child:IsA("GuiObject") then child:Destroy() end
                end
                for _, bData in ipairs(elem.Buttons) do
                    local subBtn = buttonTemplate and buttonTemplate:Clone() or Instance.new("TextButton")
                    subBtn.Visible = true
                    subBtn.ClipsDescendants = true
                    local subCorner = subBtn:FindFirstChildOfClass("UICorner")
                    if not subCorner then
                        subCorner = Instance.new("UICorner")
                        subCorner.CornerRadius = UDim.new(0, 5)
                        subCorner.Parent = subBtn
                    else
                        subCorner.CornerRadius = UDim.new(0, 5)
                    end
                    local subTitle = subBtn:FindFirstChild("Title", true) or subBtn
                    if subTitle and subTitle:IsA("TextLabel") then
                        subTitle.Font = Enum.Font.SourceSansBold
                        subTitle.RichText = true
                        subTitle.Text = bData.Title or "Btn"
                    elseif subBtn:IsA("TextButton") then
                        subBtn.Font = Enum.Font.SourceSansBold
                        subBtn.Text = bData.Title or "Btn"
                    end
                    subBtn.Parent = groupFrame

                    local trigger = subBtn:IsA("TextButton") and subBtn or subBtn:FindFirstChildOfClass("TextButton")
                    if not trigger then trigger = subBtn end
                    trigger.MouseButton1Click:Connect(function()
                        if bData.Callback then bData.Callback() end
                    end)
                end
            end

        elseif kind == "Dropdown" then
            local listFrame = itemObj:FindFirstChild("List", true)
            local searchBox = itemObj:FindFirstChild("SearchBox", true)
            local searchInput = searchBox and (searchBox:FindFirstChildOfClass("TextBox") or searchBox:FindFirstChild("Textbox", true))

            if listFrame then
                self:NormalizeScrollingFrame(listFrame)
                local tmplOpt = nil
                for _, child in ipairs(listFrame:GetChildren()) do
                    if child:IsA("GuiObject") then
                        tmplOpt = child:Clone()
                        child:Destroy()
                    end
                end

                local options = elem.Options or {}
                local isMulti = elem.Multi or false
                local selectedState = isMulti and {} or elem.Default

                local optionButtons = {}
                local function updateDropdownVisuals()
                    for optVal, btnObj in pairs(optionButtons) do
                        local tLbl = btnObj:FindFirstChild("Title", true) or (btnObj:IsA("TextLabel") and btnObj)
                        local tickImg = btnObj:FindFirstChild("Tick", true)
                        local isSelected = isMulti and (selectedState[optVal] == true) or (selectedState == optVal)

                        if tLbl and tLbl:IsA("TextLabel") then
                            tLbl.TextColor3 = isSelected and Color3.fromRGB(255, 50, 50) or Color3.fromRGB(255, 255, 255)
                        end
                        if tickImg and tickImg:IsA("ImageLabel") then
                            tickImg.Visible = isSelected
                        end
                    end
                end

                for _, optVal in ipairs(options) do
                    local optBtn = tmplOpt and tmplOpt:Clone() or Instance.new("TextButton")
                    optBtn.Visible = true
                    optBtn.Name = "OPT_" .. tostring(optVal)

                    local tLbl = optBtn:FindFirstChild("Title", true) or optBtn
                    if tLbl and tLbl:IsA("TextLabel") then
                        tLbl.RichText = true
                        tLbl.Text = tostring(optVal)
                    elseif optBtn:IsA("TextButton") then
                        optBtn.Text = tostring(optVal)
                    end
                    optBtn.Parent = listFrame
                    optionButtons[optVal] = optBtn

                    local trigger = optBtn:IsA("TextButton") and optBtn or optBtn:FindFirstChildOfClass("TextButton")
                    if not trigger then trigger = optBtn end
                    trigger.MouseButton1Click:Connect(function()
                        if isMulti then
                            selectedState[optVal] = not selectedState[optVal]
                            if not selectedState[optVal] then
                                selectedState[optVal] = nil
                            end
                            updateDropdownVisuals()
                            if elem.Callback then elem.Callback(selectedState) end
                        else
                            selectedState = optVal
                            updateDropdownVisuals()
                            if elem.Callback then elem.Callback(selectedState) end
                        end
                    end)
                end

                updateDropdownVisuals()

                if searchInput and searchInput:IsA("TextBox") then
                    searchInput:GetPropertyChangedSignal("Text"):Connect(function()
                        local q = string.lower(searchInput.Text or "")
                        for optVal, btnObj in pairs(optionButtons) do
                            if q == "" then
                                btnObj.Visible = true
                            else
                                btnObj.Visible = (string.find(string.lower(tostring(optVal)), q) ~= nil)
                            end
                        end
                    end)
                end
            end

        elseif kind == "Slider" then
            local minVal = elem.Min or 0
            local maxVal = elem.Max or 100
            local currentVal = elem.Default or minVal
            local step = elem.Increase or 1

            local valLbl = itemObj:FindFirstChild("Value", true) or itemObj:FindFirstChild("Title", true)
            local track = itemObj:FindFirstChild("Bar", true) or itemObj:FindFirstChild("Track", true) or itemObj:FindFirstChild("Slider", true)
            local fill = track and (track:FindFirstChild("Fill", true) or track:FindFirstChild("Progress", true))

            if not track then
                track = Instance.new("Frame")
                track.Name = "Track"
                track.Size = UDim2.new(0.9, 0, 0, 6)
                track.Position = UDim2.new(0.05, 0, 0, 49)
                track.BackgroundColor3 = Color3.fromRGB(35, 35, 35)
                track.BorderSizePixel = 0
                track.Active = true
                track.Parent = itemObj

                local corner = Instance.new("UICorner")
                corner.CornerRadius = UDim.new(1, 0)
                corner.Parent = track

                fill = Instance.new("Frame")
                fill.Name = "Fill"
                fill.Size = UDim2.new(0.5, 0, 1, 0)
                fill.BackgroundColor3 = Color3.fromRGB(248, 4, 46)
                fill.BorderSizePixel = 0
                fill.Parent = track

                local fillCorner = Instance.new("UICorner")
                fillCorner.CornerRadius = UDim.new(1, 0)
                fillCorner.Parent = fill
            end

            local function updateSliderVisual(val)
                val = math.clamp(val, minVal, maxVal)
                local pct = maxVal == minVal and 1 or (val - minVal) / (maxVal - minVal)
                if fill then
                    fill.Size = UDim2.new(pct, 0, 1, 0)
                end
                if valLbl and valLbl:IsA("TextLabel") then
                    valLbl.Text = elem.Title .. " : " .. tostring(val)
                end
            end
            updateSliderVisual(currentVal)

            local isDraggingSlider = false
            local function moveSlider(input)
                local absPos = track.AbsolutePosition
                local absSize = track.AbsoluteSize
                local relX = math.clamp((input.Position.X - absPos.X) / absSize.X, 0, 1)
                local rawVal = minVal + relX * (maxVal - minVal)
                local steppedVal = math.floor((rawVal - minVal) / step + 0.5) * step + minVal
                steppedVal = math.clamp(steppedVal, minVal, maxVal)
                currentVal = steppedVal
                updateSliderVisual(currentVal)
                if elem.Callback then elem.Callback(currentVal) end
            end

            track.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    isDraggingSlider = true
                    moveSlider(input)
                end
            end)
            Modules.UserInputService.InputChanged:Connect(function(input)
                if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and isDraggingSlider then
                    moveSlider(input)
                end
            end)
            Modules.UserInputService.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    isDraggingSlider = false
                end
            end)

        elseif kind == "Colorpicker" then
            itemObj.Size = UDim2.new(1, 0, 0, 50)
            local colorBox = itemObj:FindFirstChild("Colorbox", true) or itemObj:FindFirstChild("Display", true)
            local holder = itemObj:FindFirstChild("Holder", true)
            local currentColor = elem.Default or Color3.fromRGB(255, 0, 0)
            local isColorPickerOpen = false

            if holder then
                holder.Visible = false
                holder.ZIndex = math.max(holder.ZIndex, 80)
                holder.ClipsDescendants = true
                holder.Position = UDim2.new(0.5, 0, 0, 60)
                holder.Size = UDim2.new(1, 0, 0, 170)
                local control = holder:FindFirstChild("Control", true)
                if control then
                    control.Position = UDim2.new(0, 0, 0, 0)
                    control.Size = UDim2.new(1, 0, 1, 0)
                    control.ZIndex = math.max(control.ZIndex, 99)
                end
            end

            local rgbControl = holder and holder:FindFirstChild("RGB", true)
            local valueControl = holder and holder:FindFirstChild("Value", true)
            local rgbMarker = rgbControl and rgbControl:FindFirstChild("Marker")
            local valueMarker = valueControl and valueControl:FindFirstChild("Marker")
            local hue, saturation, brightness = Color3.toHSV(currentColor)
            local function updateColorVisual(col)
                currentColor = col
                hue, saturation, brightness = Color3.toHSV(col)
                if colorBox then
                    colorBox.BackgroundColor3 = col
                    local displayFrame = colorBox:FindFirstChild("Gradient", true)
                    if displayFrame then
                        displayFrame.BackgroundColor3 = col
                    end
                    local valueDisplay = holder and holder:FindFirstChild("Display", true)
                    if valueDisplay and valueDisplay:IsA("GuiObject") then
                        valueDisplay.BackgroundColor3 = col
                    end
                end
                if rgbMarker then
                    rgbMarker.Position = UDim2.new(hue, 0, 1 - saturation, 0)
                end
                if valueMarker then
                    valueMarker.Position = UDim2.new(0.5, 0, 1 - brightness, 0)
                end
            end
            updateColorVisual(currentColor)

            if colorBox then
                local trigger = colorBox:IsA("TextButton") and colorBox or colorBox:FindFirstChildOfClass("TextButton")
                if not trigger then trigger = colorBox end
                trigger.MouseButton1Click:Connect(function()
                    if holder then
                        isColorPickerOpen = not isColorPickerOpen
                        holder.Visible = isColorPickerOpen
                        if isColorPickerOpen then
                            itemObj.Size = UDim2.new(1, 0, 0, 240)
                        else
                            itemObj.Size = UDim2.new(1, 0, 0, 50)
                        end
                    end
                end)
            end

            if holder then
                local rgbImg = holder:FindFirstChild("RGB", true)
                local valueImg = holder:FindFirstChild("Value", true)
                local function updateFromPoint(image, input, mode)
                    if not image or image.AbsoluteSize.X <= 0 or image.AbsoluteSize.Y <= 0 then return end
                    local absPos = image.AbsolutePosition
                    local absSize = image.AbsoluteSize
                    local relX = math.clamp((input.Position.X - absPos.X) / absSize.X, 0, 1)
                    local relY = math.clamp((input.Position.Y - absPos.Y) / absSize.Y, 0, 1)
                    if mode == "RGB" then
                        hue = relX
                        saturation = 1 - relY
                    else
                        brightness = 1 - relY
                    end
                    local newColor = Color3.fromHSV(hue, saturation, brightness)
                    updateColorVisual(newColor)
                    if elem.Callback then elem.Callback(newColor) end
                end

                if rgbImg and rgbImg:IsA("ImageLabel") then
                    rgbImg.Active = true
                    local isDraggingColor = false
                    local function updateFromRGB(input)
                        updateFromPoint(rgbImg, input, "RGB")
                    end

                    rgbImg.InputBegan:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            isDraggingColor = true
                            updateFromRGB(input)
                        end
                    end)
                    Modules.UserInputService.InputChanged:Connect(function(input)
                        if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and isDraggingColor then
                            updateFromRGB(input)
                        end
                    end)
                    Modules.UserInputService.InputEnded:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            isDraggingColor = false
                        end
                    end)
                end
                if valueImg and valueImg:IsA("ImageLabel") then
                    valueImg.Active = true
                    local isDraggingValue = false
                    valueImg.InputBegan:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            isDraggingValue = true
                            updateFromPoint(valueImg, input, "Value")
                        end
                    end)
                    Modules.UserInputService.InputChanged:Connect(function(input)
                        if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and isDraggingValue then
                            updateFromPoint(valueImg, input, "Value")
                        end
                    end)
                    Modules.UserInputService.InputEnded:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            isDraggingValue = false
                        end
                    end)
                end
            end

        elseif kind == "Input" then
            local box = itemObj:FindFirstChildOfClass("TextBox") or itemObj:FindFirstChild("Box", true)
            if box and box:IsA("TextBox") then
                box.PlaceholderText = elem.Placeholder or "Enter..."
                box.FocusLost:Connect(function()
                    if elem.Callback then elem.Callback(box.Text) end
                end)
            end

        elseif kind == "Paragraph" then
            local descLbl = itemObj:FindFirstChild("Desc", true) or itemObj:FindFirstChild("Content", true)
            if descLbl and descLbl:IsA("TextLabel") then
                descLbl.RichText = true
                descLbl.Text = elem.Content or ""
            end

        elseif kind == "ImageLabel" then
            local imgLabel = itemObj:FindFirstChildOfClass("ImageLabel") or itemObj:FindFirstChild("Image", true)
            if imgLabel and imgLabel:IsA("ImageLabel") and elem.Image then
                imgLabel.Image = elem.Image
            end
        end
    end

    local function syncConfigCanvas()
        local contentBottom = 0
        for _, column in ipairs({tab1, tab2}) do
            local layout = column:FindFirstChildOfClass("UIListLayout")
            if layout then
                contentBottom = math.max(contentBottom, layout.AbsoluteContentSize.Y)
            end
        end
        local frameY = mainSf.AbsoluteSize.Y
        if contentBottom > frameY and frameY > 0 then
            mainSf.CanvasSize = UDim2.new(0, 0, 0, contentBottom + 12)
        else
            mainSf.CanvasSize = UDim2.new(0, 0, 0, 0)
        end
    end
    if not mainSf:GetAttribute("LonelyLibColumnsBound") then
        mainSf:SetAttribute("LonelyLibColumnsBound", true)
        for _, column in ipairs({tab1, tab2}) do
            local layout = column:FindFirstChildOfClass("UIListLayout")
            if layout then
                layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncConfigCanvas)
            end
        end
        mainSf:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncConfigCanvas)
    end
    task.defer(syncConfigCanvas)
    mainSf.CanvasPosition = Vector2.new(0, 0)
end

function Library:SetHomepageShortcut(tab1, tab2, tab3)
    if not tab1 or not tab2 or not tab3 then return end
    self.Shortcuts = {tab1, tab2, tab3}
    if self.ShortcutsFrame then
        local scBtns = {}
        for _, child in ipairs(self.ShortcutsFrame:GetChildren()) do
            if child.Name == "HOMEPAGE_BUTTON" then
                table.insert(scBtns, child)
            end
        end
        for i, tabObj in ipairs(self.Shortcuts) do
            local scBtn = scBtns[i]
            if scBtn and tabObj then
                local titleLbl = scBtn:FindFirstChild("Title", true)
                local descLbl = scBtn:FindFirstChild("Desc", true)
                local logoImg = scBtn:FindFirstChild("Logo", true)

                if titleLbl and titleLbl:IsA("TextLabel") then
                    titleLbl.RichText = true
                    titleLbl.Text = string.upper(tabObj.Title)
                end
                if descLbl and descLbl:IsA("TextLabel") then
                    descLbl.RichText = true
                    descLbl.Text = tabObj.Description or "Quick access"
                end
                if logoImg and logoImg:IsA("ImageLabel") and tabObj.Image then
                    logoImg.Image = tabObj.Image
                end

                local trigger = scBtn:IsA("TextButton") and scBtn or scBtn:FindFirstChildOfClass("TextButton")
                if not trigger then
                    trigger = Instance.new("TextButton")
                    trigger.Size = UDim2.new(1, 0, 1, 0)
                    trigger.BackgroundTransparency = 1
                    trigger.Text = ""
                    trigger.Parent = scBtn
                end
                trigger.MouseButton1Click:Connect(function()
                    self:SwitchTab("Pages")
                    self:ShowLevel(2, tabObj)
                end)
            end
        end
    end
end

function Library:AddTab(options)
    options = options or {}
    local tabTitle = Modules.getOption(options, {"Title", "Name"}, "New Tab")
    local tabDesc = Modules.getOption(options, {"Description", "Content"}, "Tab description")
    local tabImage = Modules.getOption(options, {"Image"}, "rbxassetid://112485471724320")
    local tabSide = Modules.getOption(options, {"Side"}, "Left")

    local tabObj = {
        Title = tabTitle,
        Description = tabDesc,
        Image = tabImage,
        Side = tabSide,
        Sections = {},
        Library = self
    }

    table.insert(self.Tabs, tabObj)

    function tabObj:AddSection(secOptions)
        secOptions = secOptions or {}
        local secTitle = Modules.getOption(secOptions, {"Title", "Name"}, "New Section")
        local secDesc = Modules.getOption(secOptions, {"Description", "Content"}, "Section description")
        local secImage = Modules.getOption(secOptions, {"Image"}, "rbxassetid://112485471724320")
        local secSide = Modules.getOption(secOptions, {"Side"}, "Left")
        local secType = Modules.getOption(secOptions, {"Type"}, "Button")
        local secCallback = Modules.getOption(secOptions, {"Callback", "callback"}, function() end)

        local secObj = {
            Title = secTitle,
            Description = secDesc,
            Image = secImage,
            Side = secSide,
            Type = secType,
            Callback = secCallback,
            Elements = {},
            Tab = tabObj
        }

        if secType == "Toggle" then
            table.insert(secObj.Elements, {
                Kind = "Toggle",
                Title = "Enabled",
                Default = false,
                Side = secSide,
                Callback = secCallback
            })
        end

        table.insert(tabObj.Sections, secObj)

        function secObj:AddToggle(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Toggle",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Toggle"),
                Default = Modules.getOption(eOpts, {"Default"}, false),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        function secObj:AddButton(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Button",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Button"),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        function secObj:AddButtonGroup(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "ButtonGroup",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Button Group"),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Buttons = Modules.getOption(eOpts, {"Buttons"}, {})
            })
            return secObj
        end

        function secObj:AddDropdown(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Dropdown",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Dropdown"),
                Options = Modules.getOption(eOpts, {"Options", "Values"}, {}),
                Default = Modules.getOption(eOpts, {"Default"}, nil),
                Multi = Modules.getOption(eOpts, {"Multi"}, false),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        function secObj:AddSlider(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Slider",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Slider"),
                Min = Modules.getOption(eOpts, {"Min"}, 0),
                Max = Modules.getOption(eOpts, {"Max"}, 100),
                Default = Modules.getOption(eOpts, {"Default"}, 50),
                Increase = Modules.getOption(eOpts, {"Increase"}, 1),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        function secObj:AddColorpicker(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Colorpicker",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Color Picker"),
                Default = Modules.getOption(eOpts, {"Default"}, Color3.fromRGB(255, 0, 0)),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        function secObj:AddLabel(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Label",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Label"),
                Side = Modules.getOption(eOpts, {"Side"}, "Left")
            })
            return secObj
        end

        function secObj:AddImageLabel(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "ImageLabel",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Image Label"),
                Image = Modules.getOption(eOpts, {"Image"}, "rbxassetid://112485471724320"),
                Side = Modules.getOption(eOpts, {"Side"}, "Left")
            })
            return secObj
        end

        function secObj:AddParagraph(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Paragraph",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Paragraph Title"),
                Content = Modules.getOption(eOpts, {"Content", "Description"}, "Paragraph content text goes here."),
                Side = Modules.getOption(eOpts, {"Side"}, "Left")
            })
            return secObj
        end

        function secObj:AddInput(eOpts)
            eOpts = eOpts or {}
            table.insert(secObj.Elements, {
                Kind = "Input",
                Title = Modules.getOption(eOpts, {"Title", "Name"}, "Input Field"),
                Placeholder = Modules.getOption(eOpts, {"Placeholder"}, "Enter text..."),
                Side = Modules.getOption(eOpts, {"Side"}, "Left"),
                Callback = Modules.getOption(eOpts, {"Callback", "callback"}, function() end)
            })
            return secObj
        end

        return secObj
    end

    return tabObj
end


